/**
 * Rich Ask conversations. Every answer follows one shape: short answer first, the visual, the working
 * (what was checked, cause analysis), options compared with expected bands, risks and what the agent will not do,
 * evidence, the proposed next step and follow-ups. Plant records only; rupees only for the Owner role.
 */
import type { EvidenceLabel, RoleId } from "./types";
import { at, runs } from "./data";

export type Block =
  | { k: "h"; t: string }
  | { k: "p"; t: string }
  | { k: "ul"; items: string[] }
  | { k: "trend"; title: string; values: number[]; spec: [number, number]; unit: string; from?: number }
  | { k: "compare"; title: string; rows: { m: string; unit: string; before: [number, number]; after: [number, number]; scale: [number, number]; labels?: [string, string] }[] }
  | { k: "flow"; nodes: { t: string; sub?: string; href?: string; flag?: boolean }[] }
  | { k: "table"; head: string[]; rows: (string | { t: string; href: string })[][] };
export interface Ev { label: EvidenceLabel; id: string; what: string; href: string }
export interface Opt { name: string; band: string; note: string; pick?: boolean }
export interface RichTurn {
  q: string; short: string; label: EvidenceLabel; band?: string;
  visual: Block[]; checked: string[]; cause: Block[]; options?: Opt[]; risks: string[]; wont: string[];
  ev: Ev[]; next?: { title: string; sub: string; href: string; cta: string; assignable?: boolean }; follow: string[];
}
export interface RichConv { id: string; title: string; role: RoleId; area: string; updatedAt: string; turns: RichTurn[] }

